# Try BBOX AREA ASCENDING (smallest bbox = leftmost)
def bbox_area(grid):
    bboxes = {}
    for r, row_str in enumerate(grid):
        cells = list(map(int, row_str.split()))
        for c, val in enumerate(cells):
            if val > 0 and val not in bboxes:
                bboxes[val] = {'min_r': r, 'max_r': r, 'min_c': c, 'max_c': c}
            elif val in bboxes:
                bboxes[val]['min_r'] = min(bboxes[val]['min_r'], r)
                bboxes[val]['max_r'] = max(bboxes[val]['max_r'], r)
                bboxes[val]['min_c'] = min(bboxes[val]['min_c'], c)
                bboxes[val]['max_c'] = max(bboxes[val]['max_c'], c)

    areas = {}
    for v, bb in bboxes.items():
        h = bb['max_r'] - bb['min_r'] + 1
        w = bb['max_c'] - bb['min_c'] + 1
        areas[v] = h * w
        print(f"Color {v}: bbox ({bb['min_r']},{bb['min_c']}) to ({bb['max_r']},{bb['max_c']}), size {h}x{w} = {h*w}")
    return areas

